// Isolation test (OS-12) — construct DeclarationLedger with its declared inputs and nothing
// else, then exercise every public operation. (Generated by new-object.py, rewritten for
// strict TypeScript - MF-21.)
//
// declarationAt is INVARIANT to `levels`: it reads what was appended, and the configured
// levels only decide what MAY be appended. The interface contract states this in its
// "Invariant to" cell - the only way a two-call test may return equal answers (OS-12).
import { describe, expect, it } from "vitest";
import { isUnknown } from "../src/kernel/index.js";
import { DeclarationLedger, type Unit } from "../src/catalog/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";

// A Unit is an operation INPUT, not a constructor dependency, so the test names one
// directly rather than building it through UnitRegistry: an isolation test that needs
// a second class is not testing one class in isolation (OS-12).
const u = "u1" as Unit;

describe("DeclarationLedger in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new DeclarationLedger({ levels: ["L1"] } as never)).toThrow();
    expect(() => new DeclarationLedger({ record: inMemoryRecord() } as never)).toThrow();
  });

  it("refuses a record that does not offer append and readAsOf (OS-1, a declared slot)", () => {
    expect(() => new DeclarationLedger({ record: {} as never, levels: ["L1"] })).toThrow();
  });

  it("levels answers differently when levels differs", () => {
    const record = inMemoryRecord();
    const one = new DeclarationLedger({ record, levels: ["L1"] });
    const two = new DeclarationLedger({ record, levels: ["L1", "L9"] });
    expect(one.levels()).not.toEqual(two.levels());
  });

  it("declare answers differently when record differs", () => {
    const empty = inMemoryRecord();
    const busy = inMemoryRecord();
    busy.noise();
    const a = new DeclarationLedger({ record: empty, levels: ["L1"] }).declare(u, "L1", "HUMAN");
    const b = new DeclarationLedger({ record: busy, levels: ["L1"] }).declare(u, "L1", "HUMAN");
    expect(a).not.toEqual(b);
  });

  it("declare answers differently when levels differs", () => {
    const a = new DeclarationLedger({ record: inMemoryRecord(), levels: ["L1"] }).declare(u, "L1", "HUMAN");
    const b = new DeclarationLedger({ record: inMemoryRecord(), levels: ["L9"] }).declare(u, "L1", "HUMAN");
    expect(a).not.toEqual(b);
  });

  it("declarationAt answers differently when record differs", () => {
    const declared = inMemoryRecord();
    const at = (() => {
      const d = new DeclarationLedger({ record: declared, levels: ["L1"] }).declare(u, "L1", "HUMAN");
      if (isUnknown(d)) throw new Error("refused");
      return d.at;
    })();
    const other = inMemoryRecord();
    other.noise();
    const a = new DeclarationLedger({ record: declared, levels: ["L1"] }).declarationAt(u, at);
    const b = new DeclarationLedger({ record: other, levels: ["L1"] }).declarationAt(u, at);
    expect(a).not.toEqual(b);
  });
});
